window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1027ea5f4b99157f"]={"versions": [{"id": "FIG-1027ea5f4b99157f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Mapping- und Aktivierungsdiagramm im Architekturkontext der AUTOSAR Runtime Environment (AUTOSAR_SWS_RTE). Das Diagramm visualisiert die Ausführungsumgebung und das Mapping einer Kategorie-2-Runnable-Entity (Kategorie 2 / Cat 2) innerhalb eines OS Extended Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Extended Task</strong> (äußerer orangefarbener Container): Repräsentiert einen AUTOSAR-OS-Task des Typs Extended Task mit eigenem Task-Kontext, der blockierende OS-Aufrufe (z. B. <code>WaitEvent</code>) unterstützt.\n</li><li><strong>Aktivierungs-/Dispatch-Mechanismus</strong> (schwarzer Startpunkt/Endpunkt mit Pfeil auf einen schmalen orangefarbenen horizontalen Block): Symbolisiert den Eintrittspunkt bzw. den Task-Körper und Dispatcher der RTE zur Ausführung der zugeordneten Runnable.\n</li><li><strong>Runnable Entity („Cat 2“)</strong> (graues Rechteck im unteren Bereich des Tasks): Repräsentiert eine Runnable Entity der Kategorie 2, die blockierende RTE-Aufrufe ausführen darf und daher exklusiv in einem Extended Task abgebildet werden muss.\n</li><li><strong>Ablaufpfeile</strong>: Gerichtete Verbindungslinien vom Task-Eintritt über die Dispatch-Logik direkt auf die Kategorie-2-Runnable.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Extended Task wird durch ein Betriebssystem-Ereignis (Event) oder eine Task-Aktivierung gestartet bzw. aus dem Wartezustand geweckt (schwarzer Startknoten).\n</li><li>Der Task-Ablauf erreicht den RTE-Task-Body (orangefarbener Zwischenblock).\n</li><li>Von dort erfolgt der direkte Aufruf (Dispatch) der Kategorie-2-Runnable-Entity („Cat 2“).\n</li><li>Die Runnable Entity wird innerhalb des Kontexts des Extended Tasks ausgeführt und kann blockierende Operationen (Synchronous Server Call API, Warteereignisse) nutzen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kategorie-2-Runnable-Entities (Cat 2) beinhalten blockierende Aufrufe oder Wartezustände (z. B. synchrone Client-Server-Aufrufe mit RTE-Blocking). Gemäß AUTOSAR RTE-Spezifikation dürfen Cat-2-Runnables ausschließlich auf Extended Tasks des Betriebssystems gemappt werden, da nur Extended Tasks OS-Events und den Zustand <code>WAITING</code> unterstützen. Ein Mapping auf Basic Tasks ist für Cat-2-Runnables unzulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0a2c4239223acf6c", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Mapping- und Aktivierungsdiagramm im Architekturkontext der AUTOSAR Runtime Environment (AUTOSAR_SWS_RTE). Das Diagramm visualisiert die Ausführungsumgebung und das Mapping einer Kategorie-2-Runnable-Entity (Kategorie 2 / Cat 2) innerhalb eines OS Extended Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Extended Task</strong> (äußerer orangefarbener Container): Repräsentiert einen AUTOSAR-OS-Task des Typs Extended Task mit eigenem Task-Kontext, der blockierende OS-Aufrufe (z. B. <code>WaitEvent</code>) unterstützt.\n</li><li><strong>Aktivierungs-/Dispatch-Mechanismus</strong> (schwarzer Startpunkt/Endpunkt mit Pfeil auf einen schmalen orangefarbenen horizontalen Block): Symbolisiert den Eintrittspunkt bzw. den Task-Körper und Dispatcher der RTE zur Ausführung der zugeordneten Runnable.\n</li><li><strong>Runnable Entity („Cat 2“)</strong> (graues Rechteck im unteren Bereich des Tasks): Repräsentiert eine Runnable Entity der Kategorie 2, die blockierende RTE-Aufrufe ausführen darf und daher exklusiv in einem Extended Task abgebildet werden muss.\n</li><li><strong>Ablaufpfeile</strong>: Gerichtete Verbindungslinien vom Task-Eintritt über die Dispatch-Logik direkt auf die Kategorie-2-Runnable.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Extended Task wird durch ein Betriebssystem-Ereignis (Event) oder eine Task-Aktivierung gestartet bzw. aus dem Wartezustand geweckt (schwarzer Startknoten).\n</li><li>Der Task-Ablauf erreicht den RTE-Task-Body (orangefarbener Zwischenblock).\n</li><li>Von dort erfolgt der direkte Aufruf (Dispatch) der Kategorie-2-Runnable-Entity („Cat 2“).\n</li><li>Die Runnable Entity wird innerhalb des Kontexts des Extended Tasks ausgeführt und kann blockierende Operationen (Synchronous Server Call API, Warteereignisse) nutzen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kategorie-2-Runnable-Entities (Cat 2) beinhalten blockierende Aufrufe oder Wartezustände (z. B. synchrone Client-Server-Aufrufe mit RTE-Blocking). Gemäß AUTOSAR RTE-Spezifikation dürfen Cat-2-Runnables ausschließlich auf Extended Tasks des Betriebssystems gemappt werden, da nur Extended Tasks OS-Events und den Zustand <code>WAITING</code> unterstützen. Ein Mapping auf Basic Tasks ist für Cat-2-Runnables unzulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-668e0c561988f2f3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Mapping- und Aktivierungsdiagramm im Architekturkontext der AUTOSAR Runtime Environment (AUTOSAR_SWS_RTE). Das Diagramm visualisiert die Ausführungsumgebung und das Mapping einer Kategorie-2-Runnable-Entity (Kategorie 2 / Cat 2) innerhalb eines OS Extended Tasks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Extended Task</strong> (äußerer orangefarbener Container): Repräsentiert einen AUTOSAR-OS-Task des Typs Extended Task mit eigenem Task-Kontext, der blockierende OS-Aufrufe (z. B. <code>WaitEvent</code>) unterstützt.\n</li><li><strong>Aktivierungs-/Dispatch-Mechanismus</strong> (schwarzer Startpunkt/Endpunkt mit Pfeil auf einen schmalen orangefarbenen horizontalen Block): Symbolisiert den Eintrittspunkt bzw. den Task-Körper und Dispatcher der RTE zur Ausführung der zugeordneten Runnable.\n</li><li><strong>Runnable Entity („Cat 2“)</strong> (graues Rechteck im unteren Bereich des Tasks): Repräsentiert eine Runnable Entity der Kategorie 2, die blockierende RTE-Aufrufe ausführen darf und daher exklusiv in einem Extended Task abgebildet werden muss.\n</li><li><strong>Ablaufpfeile</strong>: Gerichtete Verbindungslinien vom Task-Eintritt über die Dispatch-Logik direkt auf die Kategorie-2-Runnable.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der Extended Task wird durch ein Betriebssystem-Ereignis (Event) oder eine Task-Aktivierung gestartet bzw. aus dem Wartezustand geweckt (schwarzer Startknoten).\n</li><li>Der Task-Ablauf erreicht den RTE-Task-Body (orangefarbener Zwischenblock).\n</li><li>Von dort erfolgt der direkte Aufruf (Dispatch) der Kategorie-2-Runnable-Entity („Cat 2“).\n</li><li>Die Runnable Entity wird innerhalb des Kontexts des Extended Tasks ausgeführt und kann blockierende Operationen (Synchronous Server Call API, Warteereignisse) nutzen.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kategorie-2-Runnable-Entities (Cat 2) beinhalten blockierende Aufrufe oder Wartezustände (z. B. synchrone Client-Server-Aufrufe mit RTE-Blocking). Gemäß AUTOSAR RTE-Spezifikation dürfen Cat-2-Runnables ausschließlich auf Extended Tasks des Betriebssystems gemappt werden, da nur Extended Tasks OS-Events und den Zustand <code>WAITING</code> unterstützen. Ein Mapping auf Basic Tasks ist für Cat-2-Runnables unzulässig.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1027ea5f4b99157f", "to": "FIG-0a2c4239223acf6c", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0a2c4239223acf6c", "to": "FIG-668e0c561988f2f3", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
